import { Hono } from '/home/jack/.t3/bench-runs/2026-09-28-sonnet-5-5-rebench/att-043/clone/src/hono'
import { validator } from '/home/jack/.t3/bench-runs/2026-09-28-sonnet-5-5-rebench/att-043/clone/src/validator'
const app = new Hono()
app.post('/fd-then-parse', async (c) => {
  const fd = await c.req.formData()
  const b = await c.req.parseBody()
  return c.json({ fd: fd.get('a'), b })
})
app.post('/parse-then-fd', async (c) => {
  const b = await c.req.parseBody()
  const fd = await c.req.formData()
  return c.json({ fd: fd.get('a'), b })
})
app.post('/valid-then-parse', validator('form', (v) => v), async (c) => {
  const b = await c.req.parseBody()
  return c.json({ b, v: c.req.valid('form') })
})
app.post('/text-then-parse', async (c) => {
  const t = await c.req.text()
  const b = await c.req.parseBody()
  return c.json({ t, b })
})
app.onError((e, c) => c.json({ err: String(e) }, 500))
const mk = (kind: string) => {
  if (kind === 'mp') { const f = new FormData(); f.append('a', 'x'); return { method: 'POST', body: f } }
  return { method: 'POST', body: new URLSearchParams({ a: 'x' }) }
}
for (const p of ['fd-then-parse', 'parse-then-fd', 'valid-then-parse', 'text-then-parse'])
  for (const k of ['mp', 'url']) {
    const r = await app.request('/' + p, mk(k) as any)
    console.log(p, k, r.status, await r.text())
  }
EOF
